import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { Observable, of, tap } from 'rxjs';
import { GRADES, Grade } from './people.service';
import { SessionService } from './session.service';
import { SheetService } from './sheet.service';

export interface Rate {
  grade: Grade;
  /** A percent as text with two decimals, e.g. "12.50". */
  pct: string;
  /** The first date (yyyy-MM-dd) the rate applies on; null when it applies from the beginning of time. */
  from: string | null;
}

// The active sheet's rates, at most one per grade and from-date. A claim uses its grade's rate with
// the latest from-date on or before the claim's date (a rate with none applies from the beginning of
// time); a claim dated before every rate of its grade has none.
@Injectable({ providedIn: 'root' })
export class RatesService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly list = signal<Rate[]>([]);

  readonly rates = this.list.asReadonly();

  /** Each grade's rate in force on the sheet's today; a grade with none then is absent. */
  readonly current = computed(() => {
    const today = this.sheets.today();
    const out = new Map<Grade, Rate>();
    if (today === null) return out;
    for (const g of GRADES) {
      const r = inForce(this.list(), g, today);
      if (r) out.set(g, r);
    }
    return out;
  });

  /** Each grade's rate in force on the sheet's today, in hundredths of a percent; a grade with none then is absent. */
  readonly byGrade = computed(() => {
    const out = new Map<Grade, number>();
    for (const [g, r] of this.current()) out.set(g, hundredths(r.pct));
    return out;
  });

  /** The grade's rate in force on a date (yyyy-MM-dd), in hundredths of a percent; undefined when none. */
  rateOn(grade: Grade, date: string): number | undefined {
    const r = inForce(this.list(), grade, date);
    return r ? hundredths(r.pct) : undefined;
  }

  /** Re-read the active sheet's rates from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.list.set([]);
      return of(null);
    }
    return this.http
      .get<Rate[]>(this.url(id), { headers: this.session.headers() })
      .pipe(tap((rates) => {
        if (this.sheets.sheetId() === id) this.list.set(rates);
      }));
  }

  /** Set a grade's rate from a date (null: from the beginning of time), replacing the one it had for that from-date. */
  set(grade: Grade, pct: string, from: string | null): Observable<Rate> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .put<Rate>(`${this.url(id)}/${grade}`, { pct, from }, { headers: this.session.headers() })
      .pipe(tap((r) => this.list.update((all) => [
        ...all.filter((o) => o.grade !== r.grade || o.from !== r.from),
        r,
      ].sort(byGradeThenFrom))));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }
}

/** The grade's rate with the latest from-date on or before the date; undefined when none. */
function inForce(rates: readonly Rate[], grade: Grade, date: string): Rate | undefined {
  let best: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best;
}

function byGradeThenFrom(a: Rate, b: Rate): number {
  return a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? '');
}

/** "12.50" as 1250. */
function hundredths(pct: string): number {
  const [whole, frac = ''] = pct.split('.');
  return Number(whole) * 100 + Number((frac + '00').slice(0, 2));
}

/**
 * Cents times a rate (in hundredths of a percent) divided by 100, in cents, rounded half to even (a
 * half goes to the even cent). Worked in BigInt so it is exact for any amount.
 */
export function due(cents: number, rate: number): number {
  const product = BigInt(cents) * BigInt(rate);
  const q = product / 10000n;
  const r = product % 10000n;
  return Number(r > 5000n || (r === 5000n && q % 2n === 1n) ? q + 1n : q);
}
package net.officefloor.hq.app.sheet;

import java.time.Instant;
import java.time.LocalDate;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class SheetService {

    private final SheetRepository sheets;

    public SheetService(SheetRepository sheets) {
        this.sheets = sheets;
    }

    /** The sheet with this id; a sheet never loaded before is started empty, today at the real date. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
            } catch (DataIntegrityViolationException raced) {
                return sheets.findById(id).orElseThrow(() -> raced);
            }
        });
    }

    /**
     * The sheet's "today". Every decision that depends on the date, and every default date, uses
     * this and never the real clock.
     */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(LocalDate::now);
    }

    /** Change the sheet's "today" (the sheet is started when it was never loaded before). */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id, user);
        sheet.setToday(today);
        return sheet;
    }

    /**
     * Lock the sheet until the current transaction ends, so its claims' statuses change one at a
     * time (the sheet is started when it was never loaded before).
     */
    @Transactional
    public Sheet lock(String id, String user) {
        return sheets.findByIdForUpdate(id).orElseGet(() -> {
            load(id, user);
            return sheets.findByIdForUpdate(id).orElseThrow();
        });
    }
}
-- A rate may carry a from-date: it applies to claims dated on or after it, until a later from-date
-- of the same grade takes over. A rate with no from-date applies from the beginning of time. A grade
-- has at most one rate per from-date (and at most one without one); setting it again replaces it.
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_date);
-- A person on a sheet: a name and a grade (A, B or C). Listed in the order they were added (id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}

